var T0=Date.now();
var D=200,Q=20,V=500;
var docs=[];for(var i=0;i<D;i++){var terms={},n=5+Math.floor(R()*15);for(var k=0;k<n;k++)terms["w"+Math.floor(R()*V)]=1;docs.push(terms);}
var idx={};docs.forEach(function(dt,di){Object.keys(dt).forEach(function(w){(idx[w]=idx[w]||[]).push(di);});});
var qs=[];for(var q=0;q<Q;q++)qs.push("w"+Math.floor(R()*V));
var t0=Date.now(),hits=0;
qs.forEach(function(w){hits+=(idx[w]||[]).length;});
var tI=Date.now()-t0;
t0=Date.now();var hits2=0;
qs.forEach(function(w){for(var i=0;i<D;i++)if(docs[i][w])hits2++;});
var tB=Date.now()-t0;
console.log(JSON.stringify({id:"JAH-APX68-000001",ok:true,metrics:{docs:D,queries:Q,index_ms:tI,brute_ms:tB,speedup:+(tB/Math.max(tI,1)).toFixed(1),index_terms:Object.keys(idx).length,hit_counts_match:hits===hits2},ms:Date.now()-T0}));

